CREATE TABLE IF NOT EXISTS `dpn_medical_prescriptions` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`patient_cid` varchar(64) NOT NULL,`prescriber_cid` varchar(64) NOT NULL,`drug_id` varchar(64) NOT NULL,`dose` varchar(64) NOT NULL,`route` varchar(32) NOT NULL,`status` varchar(32) NOT NULL,`created_at` timestamp NOT NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),KEY `idx_rx_patient` (`patient_cid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
